from pathlib import Path
import os,json,hashlib,datetime
R=Path('/private/tmp/willyou-m12-t145-App046-download-A-031');raw=json.loads((R/'raw.json').read_text());assert raw['appExit']['code']==0 and raw['appExit']['signal'] is None and not raw['observedProcess']['signals'];out={'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'scope':'Exact captured completed own files only; no scans/deletes/overwrite','files':[]};dest=R/'retained-downloads';dest.mkdir(mode=0o700)
for f in raw['downloadFiles']:
 p=Path(f['path']);q=Path(f['retentionDestination']);assert q.parent==dest and q.name==f['name'] and p.parent==Path(raw['downloadsPath']);assert p.name.startswith('T145-A031-') and not q.exists();s=p.lstat();assert p.is_file() and not p.is_symlink();assert (str(s.st_dev),str(s.st_ino),s.st_size,s.st_mode&511,str(s.st_mtime_ns))==(f['dev'],f['ino'],f['bytes'],f['mode'],f['mtimeNs']);b=p.read_bytes();assert hashlib.sha256(b).hexdigest()==f['sha256'];os.link(p,q);t=q.lstat();assert (t.st_dev,t.st_ino)==(s.st_dev,s.st_ino);u=p.lstat();assert (u.st_dev,u.st_ino,u.st_size,u.st_mtime_ns)==(s.st_dev,s.st_ino,s.st_size,s.st_mtime_ns);p.unlink();out['files'].append({**f,'retained':str(q),'sameInode':True,'sourceAbsent':not p.exists()});(R/'retention.json').write_text(json.dumps(out,indent=2)+'\n')
assert len(out['files'])==len(raw['downloadFiles']);print(json.dumps({'retained':len(out['files']),'scope':out['scope']}))
